\title{Fourier Analysis on Finite Cyclic Groups:\\
Convolution, Plancherel, and the Spectral Formula for Additive Energy}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
We develop a self-contained toolkit for discrete Fourier analysis on the cyclic
group $\Z/N\Z$ and apply it to additive combinatorics. Working with the standard
additive character $e(x) = \exp(2\pi i x/N)$, we establish character orthogonality,
the convolution theorem $\dft{f \star g} = \dft{f}\cdot\dft{g}$, and the
Parseval/Plancherel identities. We then connect this analytic machinery to the
combinatorial notion of \emph{additive energy} $E[A]$ of a set $A \subseteq \Z/N\Z$,
proving the central spectral identity
\[
  E[A] = \frac{1}{N}\sum_{k}\norm{\dft{\one_A}(k)}^4,
\]
together with its immediate corollary $E[A] \ge \abs{A}^4/N$. The development
isolates the representation-counting role of self-convolution, namely
$(\one_A \star \one_A)(a)$ equals the number of ordered pairs in $A \times A$
summing to $a$, and shows how Plancherel converts the $\ell^2$ norm of that count
into the fourth moment of the spectrum. These results constitute the Fourier-analytic
backbone of Roth-type theorems and of the Balog--Szemer\'edi--Gowers theorem. We
record proof sketches, discuss algorithmic content, and outline several concrete
extensions, including a general finite-abelian-group version and an equality
characterization of the energy lower bound.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Additive combinatorics studies the interaction between the additive structure of a
set and its size. A central organizing quantity is the \emph{additive energy} of a
finite set $A$ in an abelian group, defined as the number of additive quadruples
\[
  E[A] = \#\{(a,b,c,d) \in A^4 : a + b = c + d\}.
\]
Additive energy interpolates between two extremes: arithmetic-progression-like sets
maximize energy (of order $\abs{A}^3$), whereas generic ``random'' sets minimize it
(of order $\abs{A}^4/N$ in $\Z/N\Z$). The dichotomy \emph{structure vs.\ randomness}
is measured precisely by where a given set falls between these extremes.

The most powerful lens for analyzing additive energy is Fourier analysis on finite
abelian groups: the discrete Fourier transform diagonalizes convolution, and
additive energy is at heart an $\ell^2$ quantity built from a self-convolution. The
purpose of this paper is to make that connection completely explicit on the cyclic
group $\Z/N\Z$, deriving the spectral formula for additive energy from first
principles.

\subsection{Contributions}
We prove, for every $N \ge 1$:
\begin{enumerate}
  \item \textbf{Character orthogonality}: $\sum_i e(t\cdot i) = N\,[t=0]$.
  \item \textbf{The convolution theorem}: $\dft{f \star g}(k) = \dft{f}(k)\,\dft{g}(k)$.
  \item \textbf{Parseval} (sesquilinear) and \textbf{Plancherel} (norm form).
  \item \textbf{Representation counting}: $(\one_A \star \one_A)(a) = r_A(a)$ and
        $E[A] = \sum_a r_A(a)^2$.
  \item \textbf{The spectral formula}: $E[A] = N^{-1}\sum_k \norm{\dft{\one_A}(k)}^4$,
        with corollary $E[A] \ge \abs{A}^4/N$.
\end{enumerate}

\subsection{Conventions}
Throughout, $N \ge 1$ is fixed and $\G = \Z/N\Z$. We use the standard additive
character $e\colon \G \to \C$, $e(x) = \exp(2\pi i\,\tilde x/N)$, where
$\tilde x \in \{0,\dots,N-1\}$ is the canonical representative. It satisfies
$e(x+y) = e(x)e(y)$, $\abs{e(x)} = 1$, and $\overline{e(x)} = e(-x)$. The discrete
Fourier transform uses the convention
\[
  \dft{f}(k) = \sum_{j \in \G} e(-jk)\, f(j),
\]
placing the normalizing factor $N$ on the inverse transform. Consequently
Plancherel carries the factor $N$ on the spectral side, and the energy identity
carries the reciprocal factor $1/N$. Unqualified sums range over all of $\G$.

\section{Preliminaries: characters and orthogonality}

The characters of $\G = \Z/N\Z$ are exactly the maps $x \mapsto e(kx)$ for
$k \in \G$; these are the irreducible unitary representations of the abelian group
and form an orthogonal basis of $\C^\G$.

\begin{lemma}[Conjugation of the character]\label{lem:conj}
For all $x \in \G$, $\overline{e(x)} = e(-x)$.
\end{lemma}
\begin{proof}[Proof sketch]
Since $e$ maps into the unit circle, $\abs{e(x)} = 1$, so the conjugate of $e(x)$
equals its inverse. The inverse is $e(-x)$ because $e(x)e(-x) = e(0) = 1$.
\end{proof}

\begin{lemma}[Character orthogonality]\label{lem:orth}
For every $t \in \G$,
\[
  \sum_{i \in \G} e(t\cdot i) =
  \begin{cases} N, & t = 0,\\ 0, & t \neq 0.\end{cases}
\]
\end{lemma}
\begin{proof}[Proof sketch]
If $t = 0$ every summand is $1$ and the sum is $\abs{\G} = N$. If $t \neq 0$, the map
$i \mapsto e(t\cdot i)$ is a nontrivial character $\chi$ (because $e$ is primitive).
Choosing $i_0$ with $\chi(i_0) \neq 1$ and substituting $i \mapsto i + i_0$ gives
$\chi(i_0)\,S = S$ for $S = \sum_i \chi(i)$, forcing $S = 0$.
\end{proof}

This single lemma is the source of every subsequent cancellation.

\section{Convolution and the convolution theorem}

\begin{definition}[Indicator]
For finite $s \subseteq \G$, $\one_s(x) = 1$ if $x \in s$ and $0$ otherwise.
\end{definition}

\begin{definition}[Cyclic convolution]
For $f,g\colon \G \to \C$, $(f \star g)(x) = \sum_{y \in \G} f(y)\, g(x - y)$.
\end{definition}

\begin{theorem}[Convolution theorem]\label{thm:conv}
For all $f,g\colon \G \to \C$ and all $k \in \G$,
\[
  \dft{(f \star g)}(k) = \dft{f}(k)\,\dft{g}(k).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Expand $\dft{(f\star g)}(k) = \sum_x\big(\sum_y f(y)g(x-y)\big)e(-kx)$. Fix $y$ and
substitute $x = y+z$; since $z \mapsto y+z$ is a bijection of $\G$ the range is
unchanged. Using $e(-kx) = e(-ky)e(-kz)$ the double sum factors as
$\big(\sum_y f(y)e(-ky)\big)\big(\sum_z g(z)e(-kz)\big) = \dft{f}(k)\dft{g}(k)$.
\end{proof}

\section{Parseval and Plancherel}

\begin{theorem}[Parseval]\label{thm:parseval}
For all $f,g\colon \G \to \C$,
\[
  \sum_k \dft{f}(k)\,\overline{\dft{g}(k)} = N\sum_j f(j)\,\overline{g(j)}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Write $\dft{f}(k) = \sum_j f(j)e(-jk)$ and, using Lemma~\ref{lem:conj},
$\overline{\dft{g}(k)} = \sum_\ell \overline{g(\ell)}\,e(\ell k)$. Multiply and sum
over $k$:
\[
  \sum_k \dft{f}(k)\overline{\dft{g}(k)}
  = \sum_j\sum_\ell f(j)\overline{g(\ell)}\sum_k e\big((\ell-j)k\big).
\]
By Lemma~\ref{lem:orth} the inner sum is $N$ if $\ell=j$ and $0$ otherwise;
collapsing to the diagonal gives $N\sum_j f(j)\overline{g(j)}$.
\end{proof}

\begin{theorem}[Plancherel]\label{thm:plancherel}
For all $f\colon \G \to \C$,
\[
  \sum_k \norm{\dft{f}(k)}^2 = N\sum_j \norm{f(j)}^2.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Set $g = f$ in Theorem~\ref{thm:parseval} and use $z\overline z = \norm{z}^2$.
Both sides are real and nonnegative.
\end{proof}

\section{Additive energy via Fourier}

\begin{definition}[Representation count]
For finite $s \subseteq \G$ and $a \in \G$,
$r_s(a) = \#\{(x,y) \in s \times s : x + y = a\}$.
\end{definition}

\begin{lemma}[Self-convolution counts representations]\label{lem:convind}
For all finite $s \subseteq \G$ and $a \in \G$,
$(\one_s \star \one_s)(a) = r_s(a)$.
\end{lemma}
\begin{proof}[Proof sketch]
$(\one_s\star\one_s)(a) = \sum_y \one_s(y)\one_s(a-y)$; each summand is $1$ exactly
when $y \in s$ and $a-y \in s$. The map $y \mapsto (y,a-y)$ is a bijection onto
$\{(x,y)\in s\times s : x+y=a\}$, so the sum equals $r_s(a)$.
\end{proof}

\begin{lemma}[Energy decomposition]\label{lem:energydecomp}
For all finite $s \subseteq \G$, $E[s] = \sum_{a \in \G} r_s(a)^2$.
\end{lemma}
\begin{proof}[Proof sketch]
Partition the additive quadruples by the common sum $t = a+b = c+d$. For each $t$
there are $r_s(t)$ pairs $(a,b)$ and independently $r_s(t)$ pairs $(c,d)$, giving
$r_s(t)^2$ quadruples; sum over $t$.
\end{proof}

\begin{theorem}[Spectral formula for additive energy]\label{thm:energy}
For all finite $A \subseteq \G$,
\[
  E[A] = \frac{1}{N}\sum_k \norm{\dft{\one_A}(k)}^4.
\]
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:energydecomp} and Lemma~\ref{lem:convind},
$E[A] = \sum_a r_A(a)^2 = \sum_a \norm{(\one_A\star\one_A)(a)}^2$ (the counts are
nonnegative reals). Apply Plancherel (Theorem~\ref{thm:plancherel}) to
$h = \one_A\star\one_A$: $\sum_a \norm{h(a)}^2 = N^{-1}\sum_k \norm{\dft{h}(k)}^2$.
By the convolution theorem (Theorem~\ref{thm:conv}),
$\dft{h}(k) = \dft{\one_A}(k)^2$, so $\norm{\dft{h}(k)}^2 = \norm{\dft{\one_A}(k)}^4$.
\end{proof}

\begin{corollary}[Energy lower bound]\label{cor:lower}
For all finite $A \subseteq \G$, $E[A] \ge \abs{A}^4/N$.
\end{corollary}
\begin{proof}[Proof sketch]
Every term in the spectral sum of Theorem~\ref{thm:energy} is nonnegative. Keeping
only $k=0$ and using $\dft{\one_A}(0) = \sum_j \one_A(j) = \abs{A}$ gives
$E[A] \ge N^{-1}\abs{A}^4$.
\end{proof}

\begin{remark}
The bound is sharp: equality forces all higher-frequency terms to vanish, i.e.\
$\one_A$ is constant. Over prime $N$ this means $A \in \{\varnothing, \G\}$; in
general it classifies the equality sets as cosets of subgroups.
\end{remark}

\subsection*{A worked example}
Take $N = 7$ and $A = \{0,1,2,4\}$, so $\abs{A}=4$. The representation counts are
$r_A = (1,3,3,2,3,2,2)$ for $a = 0,\dots,6$, summing to $16 = \abs{A}^2$. By
Lemma~\ref{lem:energydecomp}, $E[A] = \sum_a r_A(a)^2 = 1+9+9+4+9+4+4 = 40$, which
also equals the brute-force quadruple count. The zeroth Fourier coefficient is
$\dft{\one_A}(0) = 4$, contributing $\tfrac17 \cdot 4^4 = 256/7 \approx 36.57$, and the
full spectral sum $\tfrac17\sum_k\abs{\dft{\one_A}(k)}^4$ equals exactly $40$,
confirming Theorem~\ref{thm:energy}. Corollary~\ref{cor:lower} gives
$E[A] \ge 256/7$, and the gap $40 - 256/7 = 24/7$ is precisely the contribution of
the nonzero frequencies. For comparison, in $\Z/11\Z$ the progression
$\{0,1,2,3,4\}$ has energy $85$ while the spread set $\{0,1,3,7,9\}$ has energy $69$;
both exceed $5^4/11 \approx 56.8$, with the more structured set sitting further above
the bound.

\section{Algorithmic content}

\paragraph{Direct vs.\ spectral energy.}
The naive computation of $E[A]$ costs $O(\abs{A}^4)$, or $O(N^2)$ via
$E[A] = \sum_a r_A(a)^2$. The spectral formula gives an $O(N\log N)$ route:
compute $\dft{\one_A}$ by an FFT, then evaluate $N^{-1}\sum_k \abs{\dft{\one_A}(k)}^4$
in $O(N)$. Theorem~\ref{thm:energy} certifies equality of the two procedures.

\paragraph{Spectral convolution.}
The convolution theorem yields the FFT convolution algorithm: transform, multiply
pointwise, invert, reducing $O(N^2)$ to $O(N\log N)$. Lemma~\ref{lem:convind} then
identifies the self-convolution of an indicator with its representation function.

\section{Applications}

\paragraph{Roth's theorem.} The number of three-term progressions in
$A \subseteq \Z/N\Z$ ($N$ odd) equals
$N^{-1}\sum_k \dft{\one_A}(k)^2\,\dft{\one_A}(-2k)$, with $k=0$ main term
$\abs{A}^3/N$. Theorems~\ref{thm:conv} and~\ref{thm:plancherel} are precisely the
ingredients of the density-increment proof.

\paragraph{Balog--Szemer\'edi--Gowers.} Additive energy is the quantity governed by
this theorem; Theorem~\ref{thm:energy} and Corollary~\ref{cor:lower} are the
standard tools for computing and bounding it.

\paragraph{Signal processing.} The same three pillars power fast filtering
(convolution theorem), energy conservation across the spectrum (Plancherel), and
frequency separation (orthogonality).

\section{Discussion}

The development is minimal: a single orthogonality lemma drives everything. The chain
\[
  E[A] = \sum_a r_A(a)^2 = \sum_a \abs{(\one_A\star\one_A)(a)}^2
       = \tfrac1N\sum_k \abs{\dft{\one_A}(k)^2}^2 = \tfrac1N\sum_k \abs{\dft{\one_A}(k)}^4
\]
is short, but each link is a genuine theorem. A subtlety is normalization: placing
$N$ on the inverse transform makes the forward transform a pure sum at the cost of a
$1/N$ in the energy identity; a reader using another convention must track the
constant accordingly.

\section{Future directions}

\begin{description}
  \item[C1.] Energy lower bound via the sumset: $E[A] \ge \abs{A}^4/\abs{A+A}$,
  refining Corollary~\ref{cor:lower} (since $\abs{A+A}\le N$), via Cauchy--Schwarz on
  $\sum_{t\in A+A} r_A(t) = \abs{A}^2$ and $\sum_t r_A(t)^2 = E[A]$.
  \item[C2.] Spectral count of 3-APs: for $\gcd(2,N)=1$ the count equals
  $N^{-1}\sum_k \dft{\one_A}(k)^2\,\dft{\one_A}(-2k)$, $k=0$ term $\abs{A}^3/N$.
  \item[C3.] Convolution $\ell^2$ identity:
  $\sum_a \norm{(f\star g)(a)}^2 = N^{-1}\sum_k \norm{\dft{f}(k)}^2\norm{\dft{g}(k)}^2$,
  generalizing Theorem~\ref{thm:energy}.
  \item[C4.] Arbitrary finite abelian groups: re-prove Theorem~\ref{thm:energy} over
  general finite abelian $G$ with $N := \abs{G}$ using character-Fourier transforms.
  \item[C5.] Equality characterization: $E[A] = \abs{A}^4/N$ iff $\dft{\one_A}$ is
  supported only at $k=0$, i.e.\ $\one_A$ is constant; over prime $N$ this forces
  $A \in \{\varnothing, G\}$.
\end{description}

\section{Conclusion}
We gave a complete, self-contained derivation of the spectral formula for additive
energy on $\Z/N\Z$, resting on character orthogonality, the convolution theorem, and
Plancherel's identity. The identity $E[A] = N^{-1}\sum_k \abs{\dft{\one_A}(k)}^4$ and
its corollary $E[A] \ge \abs{A}^4/N$ are the analytic backbone of Roth-type theorems
and the Balog--Szemer\'edi--Gowers theorem, and the toolkit is directly reusable for
the directions above.

