function DFT(N, f):
    for k in 0..N-1:
        f_hat[k] <- 0
        for j in 0..N-1:
            f_hat[k] <- f_hat[k] + exp(-2*pi*i*(j*k)/N) * f[j]
    return f_hat

function IDFT(N, f_hat):
    for j in 0..N-1:
        f[j] <- 0
        for k in 0..N-1:
            f[j] <- f[j] + exp(+2*pi*i*(j*k)/N) * f_hat[k]
        f[j] <- f[j] / N
    return f

