function SPECTRAL_CONV(N, f, g):
    f_hat <- DFT(N, f)
    g_hat <- DFT(N, g)
    for k in 0..N-1:
        prod[k] <- f_hat[k] * g_hat[k]
    return IDFT(N, prod)

function SPECTRAL_ENERGY(N, A):
    for x in 0..N-1:
        ind[x] <- 1 if x in A else 0
    a_hat <- DFT(N, ind)
    E <- 0
    for k in 0..N-1:
        E <- E + |a_hat[k]|^4
    return E / N

function ENERGY_LOWER_BOUND(N, A):
    return |A|^4 / N        # the k = 0 term of the spectral sum
